mapper.select:
SELECT USER_ID AS userId , USER_NM AS userNm , DEPT_NM AS deptNm , JOB_ROLE AS jobRole , POSITION_NM AS positionNm , CAREER_YEARS AS careerYears , CURRENT_LOAD AS currentLoad , JOIN_DT AS joinDt , AUTH_LEVEL AS authLevel , USE_YN AS useYn FROM TB_USER WHERE DEL_YN = 'N'
AND USER_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY JOIN_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO TB_USER (
    USER_ID, USER_NM, USER_PWD, DEPT_NM, JOB_ROLE, POSITION_NM, 
    CAREER_YEARS, JOB_FIELD, CURRENT_LOAD, JOIN_DT, AUTH_LEVEL, USE_YN
) VALUES (
    #{userId}, #{userNm}, #{userPwd}, #{deptNm}, #{jobRole}, #{positionNm}, 
    #{careerYears}, #{jobField}, #{currentLoad}, #{joinDt}, #{authLevel}, #{useYn}
)

mapper.update:
UPDATE TB_USER SET
      USER_NM       = #{userNm}
    , DEPT_NM       = #{deptNm}
    , JOB_ROLE      = #{jobRole}
    , POSITION_NM   = #{positionNm}
    , CAREER_YEARS  = #{careerYears}
    , CURRENT_LOAD  = #{currentLoad}
    , AUTH_LEVEL    = #{authLevel}
    , USE_YN        = #{useYn}
    , LAST_UPDUSR_ID = #{lastUpdusrId}
    , LAST_UPDT_PNTTM = NOW()
WHERE USER_ID = #{userId}

UPDATE TB_USER SET 
      DEL_YN = 'Y'
    , LAST_UPDUSR_ID = #{lastUpdusrId}
    , LAST_UPDT_PNTTM = NOW()
WHERE USER_ID = #{userId}
